const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Great Lakes geometries (approximate boundaries)
  const lakes = {
    'Superior': ee.Geometry.Polygon([
      [[-92.0, 46.5], [-92.0, 48.5], [-84.5, 48.5], [-84.5, 46.5], [-92.0, 46.5]]
    ]),
    'Michigan': ee.Geometry.Polygon([
      [[-87.5, 41.5], [-87.5, 46.0], [-84.5, 46.0], [-84.5, 41.5], [-87.5, 41.5]]
    ]),
    'Huron': ee.Geometry.Polygon([
      [[-84.5, 43.0], [-84.5, 46.5], [-79.5, 46.5], [-79.5, 43.0], [-84.5, 43.0]]
    ]),
    'Erie': ee.Geometry.Polygon([
      [[-83.5, 41.3], [-83.5, 42.9], [-78.9, 42.9], [-78.9, 41.3], [-83.5, 41.3]]
    ]),
    'Ontario': ee.Geometry.Polygon([
      [[-79.8, 43.2], [-79.8, 44.3], [-76.0, 44.3], [-76.0, 43.2], [-79.8, 43.2]]
    ])
  };

  const date = '2018-02-14';

  // Try MODIS Aqua Snow Cover (afternoon pass)
  let collection = ee.ImageCollection('MODIS/006/MYD10A1')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .select('NDSI_Snow_Cover');

  const size = collection.size().getInfo();
  console.log(`MODIS Aqua images found: ${size}`);

  if (size === 0) {
    // Fallback to Terra (morning pass)
    collection = ee.ImageCollection('MODIS/006/MOD10A1')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .select('NDSI_Snow_Cover');

    const terraSize = collection.size().getInfo();
    console.log(`MODIS Terra images found: ${terraSize}`);

    if (terraSize === 0) {
      console.log('No MODIS data available for this date');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  const image = collection.mosaic();

  // NDSI_Snow_Cover: 0-100 = NDSI snow cover, 200 = missing data, 201 = no decision, 
  // 211 = night, 237 = inland water, 239 = ocean, 250 = cloud, 254 = detector saturated, 255 = fill
  // We want ice/snow coverage (values 0-100, higher values indicate more ice/snow)
  const iceMask = image.gte(10).and(image.lte(100)); // NDSI > 10% indicates ice/snow

  const results = {};

  // Calculate ice coverage for each lake
  for (const [name, geometry] of Object.entries(lakes)) {
    const stats = image.updateMask(iceMask).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });

    const icePixels = stats.get('NDSI_Snow_Cover').getInfo();

    // Also get total pixels to calculate percentage
    const totalStats = image.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });

    const totalPixels = totalStats.get('NDSI_Snow_Cover').getInfo();

    if (icePixels === null || totalPixels === null || totalPixels === 0) {
      console.log(`${name}: No valid data`);
      results[name] = 0;
    } else {
      const percentage = (icePixels / totalPixels) * 100;
      results[name] = percentage;
      console.log(`${name}: ${percentage.toFixed(1)}% ice coverage (${icePixels} pixels)`);
    }
  }

  // Check if we have valid results
  const validResults = Object.values(results).filter(v => v !== null && !isNaN(v));
  if (validResults.length === 0) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare Erie to other lakes
  const erieIce = results['Erie'];
  const otherLakes = ['Superior', 'Michigan', 'Huron', 'Ontario'];

  let erieHasMore = true;
  for (const lake of otherLakes) {
    if (results[lake] >= erieIce) {
      erieHasMore = false;
      console.log(`${lake} has equal or more ice than Erie`);
      break;
    }
  }

  if (erieHasMore) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
